window.ATLAS_THREE=[{"id":"s-orbit","mode":"orbit","title":"自由观察与缩放","cat":"模型观察","tags":["数码","珠宝","工业"],"brief":"让用户从自己的角度观察体积与轮廓。","label":"观察距离","hint":"拖动模型或使用方向键旋转，滑块控制远近。","steps":"拖动模型或使用方向键旋转，滑块控制远近。","level":"入门","adapt":"替换程序化模型为优化后的 GLB；保留视角重置与触控替代。","limit":"不要让旋转抢走整页滚动；提供明确的初始视角。","type":"three","file":"three/orbit.html","image":"assets/three-orbit.webp","initial":35,"color":"#d8e866"},{"id":"s-material","mode":"material","title":"金属与粗糙度实验","cat":"材质光照","tags":["家居","美妆","汽车"],"brief":"在同一灯光下比较颜色、粗糙度和金属感。","label":"表面粗糙度","hint":"移动滑块改变粗糙度，再切换金属模式与颜色。","steps":"移动滑块改变粗糙度，再切换金属模式与颜色。","level":"进阶","adapt":"换成真实 PBR 贴图和校准过的环境光。","limit":"示例材质是视觉演示，不代表真实产品的物理测量。","type":"three","file":"three/material.html","image":"assets/three-material.webp","initial":35,"color":"#a7bff1"},{"id":"s-explode","mode":"explode","title":"可控爆炸拆解","cat":"结构讲解","tags":["工业","电子","教育"],"brief":"把看不见的层次展开，解释部件之间的关系。","label":"拆解程度","hint":"拖动滑块展开各层，反向拖动重新组合。","steps":"拖动滑块展开各层，反向拖动重新组合。","level":"进阶","adapt":"给真实模型按部件命名，逐个设置拆解方向与距离。","limit":"装配关系需工程审核；不要把演示当成安装指导。","type":"three","file":"three/explode.html","image":"assets/three-explode.webp","initial":35,"color":"#ebae8c"},{"id":"s-clipping","mode":"clipping","title":"动态剖切观察","cat":"结构讲解","tags":["建筑","设备","教学"],"brief":"移动一个平面，观察壳体内的构造。","label":"剖切位置","hint":"移动滑块让剖切面穿过产品，旋转查看内部。","steps":"移动滑块让剖切面穿过产品，旋转查看内部。","level":"进阶","adapt":"使用局部 clipping plane；需要封口时补充 stencil 或实体布尔。","limit":"这个示例没有剖面封口，也不是医疗或工程诊断工具。","type":"three","file":"three/clipping.html","image":"assets/three-clipping.webp","initial":60,"color":"#d8e866"},{"id":"s-hotspots","mode":"hotspots","title":"点击部件与高亮","cat":"结构讲解","tags":["商品","展品","科普"],"brief":"从物体出发阅读信息，不必来回对应图例。","label":"部件序号","hint":"点击三维表面选中部件；也可用滑块依次选择。","steps":"点击三维表面选中部件；也可用滑块依次选择。","level":"进阶","adapt":"用射线拾取绑定产品部件、说明和可访问的按钮列表。","limit":"避免仅靠颜色表达选中，始终同步部件名称。","type":"three","file":"three/hotspots.html","image":"assets/three-hotspots.webp","initial":35,"color":"#d8e866"},{"id":"s-configurator","mode":"configurator","title":"模块化家具配置","cat":"产品配置","tags":["家具","空间","定制"],"brief":"配置改变立即反映到尺寸、颜色和部件。","label":"宽深比例","hint":"调节宽深，切换颜色，启用或隐藏扶手。","steps":"调节宽深，切换颜色，启用或隐藏扶手。","level":"进阶","adapt":"替换示例比例为经过校验的尺寸选项和可组合规则。","limit":"参数化外观不等于可生产尺寸，需要业务约束。","type":"three","file":"three/configurator.html","image":"assets/three-configurator.webp","initial":35,"color":"#a7bff1"},{"id":"s-morph","mode":"morph","title":"球体与方体变形","cat":"动效叙事","tags":["品牌","艺术","概念"],"brief":"用连续形变表现状态转换和形态探索。","label":"形态混合","hint":"拖动滑块，观察球体平滑变成立方体。","steps":"拖动滑块，观察球体平滑变成立方体。","level":"进阶","adapt":"为真实模型准备相同拓扑的 morph targets。","limit":"形变适合表达故事，不适合伪装真实产品结构。","type":"three","file":"three/morph.html","image":"assets/three-morph.webp","initial":35,"color":"#ebae8c"},{"id":"s-particles","mode":"particles","title":"粒子形态重组","cat":"动效叙事","tags":["发布会","科技","片头"],"brief":"让点云在两种空间结构之间重新组织。","label":"聚合形态","hint":"从球体点云过渡到环形，再播放循环。","steps":"从球体点云过渡到环形，再播放循环。","level":"进阶","adapt":"将粒子目标采样到自己的文字或模型表面。","limit":"控制粒子数；给低性能设备保留静态封面。","type":"three","file":"three/particles.html","image":"assets/three-particles.webp","initial":35,"color":"#d8e866"},{"id":"s-instancing","mode":"instancing","title":"阵列与群体波动","cat":"程序化空间","tags":["数据","展览","科技"],"brief":"同一个模块，构成可变化的空间节奏。","label":"波动相位","hint":"拖动相位或播放，观察 225 个实例的变化。","steps":"拖动相位或播放，观察 225 个实例的变化。","level":"进阶","adapt":"把柱高映射到真实数据；用实例化减少绘制调用。","limit":"如果表示数据，应说明坐标、数值和单位。","type":"three","file":"three/instancing.html","image":"assets/three-instancing.webp","initial":35,"color":"#d8e866"},{"id":"s-path","mode":"path","title":"沿曲线的空间运动","cat":"空间导航","tags":["运输","过程","导览"],"brief":"沿着路径解释移动过程，而不是突然跳转。","label":"路径进度","hint":"拖动进度，观察物体沿闭合曲线运动。","steps":"拖动进度，观察物体沿闭合曲线运动。","level":"进阶","adapt":"替换 Catmull-Rom 控制点，并设计速度与停留节点。","limit":"运动路径是示意；真实路线需使用对应空间数据。","type":"three","file":"three/path.html","image":"assets/three-path.webp","initial":35,"color":"#a7bff1"},{"id":"s-room","mode":"room","title":"三维展廊浏览","cat":"空间导航","tags":["艺术","作品集","房产"],"brief":"在空间中逐个观察展品，保留位置关系。","label":"展廊位置","hint":"移动滑块横向浏览五个展品，也可拖动观察。","steps":"移动滑块横向浏览五个展品，也可拖动观察。","level":"进阶","adapt":"用真实场景替换程序展廊，加入展品信息和可跳转目录。","limit":"先保证用户能到达目标，再设计自由漫游。","type":"three","file":"three/room.html","image":"assets/three-room.webp","initial":35,"color":"#ebae8c"},{"id":"s-scroll","mode":"scroll","title":"滚动驱动镜头叙事","cat":"动效叙事","tags":["品牌","新品","故事"],"brief":"滚动进度与镜头、结构展开保持一致。","label":"叙事进度","hint":"在下方故事框内滚动，或用滑块推进三个阶段。","steps":"在下方故事框内滚动，或用滑块推进三个阶段。","level":"进阶","adapt":"把局部滚动容器换成页面章节并设置镜头关键帧。","limit":"尊重减少动态偏好；核心信息不应只出现在动画中。","type":"three","file":"three/scroll.html","image":"assets/three-scroll.webp","initial":35,"color":"#d8e866"},{"id":"s-projection","mode":"projection","title":"透视与正交比较","cat":"模型观察","tags":["工业","建筑","图解"],"brief":"同一物体，比较空间透视与无透视投影。","label":"视场 / 正交倍率","hint":"切换正交投影，再用滑块比较视场与倍率。","steps":"切换正交投影，再用滑块比较视场与倍率。","level":"入门","adapt":"技术图解用正交，空间感呈现用透视；保持目标位置一致。","limit":"切换相机后避免把视觉大小变化误读为产品尺寸变化。","type":"three","file":"three/projection.html","image":"assets/three-projection.webp","initial":35,"color":"#d8e866"},{"id":"s-lighting","mode":"lighting","title":"交互式环绕布光","cat":"材质光照","tags":["摄影","产品","材料"],"brief":"改变灯光方向，观察轮廓、反射和阴影明暗。","label":"主光方位","hint":"旋转主光方位，切换冷暖光，比较高光变化。","steps":"旋转主光方位，切换冷暖光，比较高光变化。","level":"入门","adapt":"用自己的灯位、色温和环境图建立摄影布光预览。","limit":"屏幕表现受显示器影响，不代表实物色准。","type":"three","file":"three/lighting.html","image":"assets/three-lighting.webp","initial":35,"color":"#a7bff1"},{"id":"s-turntable","mode":"turntable","title":"可暂停产品转台","cat":"产品配置","tags":["电商","工业","展示"],"brief":"让产品按用户控制的节奏完成一圈展示。","label":"转台角度","hint":"拖动角度，或点击播放后随时暂停。","steps":"拖动角度，或点击播放后随时暂停。","level":"入门","adapt":"替换为自己的产品，默认静止，播放由用户启动。","limit":"不要把自动旋转设成唯一观察方式。","type":"three","file":"three/turntable.html","image":"assets/three-turntable.webp","initial":35,"color":"#ebae8c"},{"id":"s-measure","mode":"measure","title":"尺寸包围盒演示","cat":"结构讲解","tags":["家居","包装","空间"],"brief":"把模型范围与尺寸提示放在同一画面。","label":"整体比例","hint":"移动滑块放大缩小，观察包围盒与示例单位。","steps":"移动滑块放大缩小，观察包围盒与示例单位。","level":"入门","adapt":"从模型包围盒读取尺寸，校验模型单位后再显示真实数值。","limit":"当前使用抽象单位 u，不是毫米，不可用于实际测量。","type":"three","file":"three/measure.html","image":"assets/three-measure.webp","initial":35,"color":"#d8e866"},{"id":"s-drag","mode":"drag","title":"三维物体平面拖放","cat":"空间导航","tags":["布局","编辑器","教育"],"brief":"选中并移动物体，直接编排空间关系。","label":"选中物体水平位置","hint":"拖动平面上的物体，或从列表选择物体，使用方向按钮和两轴滑块调整；重置恢复全部位置。","steps":"拖动平面上的物体，或从列表选择物体，使用方向按钮和两轴滑块调整；重置恢复全部位置。","level":"进阶","adapt":"增加吸附、边界、撤销和碰撞约束后用于空间布局。","limit":"这是平面拖动；不包含刚体物理或碰撞检测。","type":"three","file":"three/drag.html","image":"assets/three-drag.webp","initial":35,"color":"#d8e866"},{"id":"s-wave","mode":"wave","title":"程序化波浪表面","cat":"程序化空间","tags":["艺术","背景","材质"],"brief":"用顶点变化形成连续起伏的空间表面。","label":"波浪相位","hint":"拖动相位或播放变化，切换线框观察网格。","steps":"拖动相位或播放变化，切换线框观察网格。","level":"进阶","adapt":"将 CPU 顶点更新迁移到 shader，以支持更大规模网格。","limit":"视觉波浪不是流体求解；不要用于物理预测。","type":"three","file":"three/wave.html","image":"assets/three-wave.webp","initial":35,"color":"#a7bff1"}];
